local function optional(f)local ok,v=pcall(f);return ok and v or{unavailable=tostring(v)}end
local function contains(t,n)for k,v in pairs(t or{})do if k==n or v==n then return true end end;return false end
script.on_init(function()
 local name='tech-priests-emergency-smelter';local p=assert(prototypes.entity[name]);local f=game.forces.player;local s=game.surfaces[1];s.request_to_generate_chunks({20,20},1);s.force_generate_chunk_requests();local tiles={};for x=10,40 do for y=10,40 do tiles[#tiles+1]={name='grass-1',position={x,y}}end end;s.set_tiles(tiles,true)
 for _,e in pairs(s.find_entities_filtered{area={{10,10},{40,40}},type={'tree','simple-entity','cliff'}})do e.destroy()end
 local e=assert(s.create_entity{name=name,position={20.5,20.5},force=f});local dirs={};for _,d in ipairs({0,4,8,12})do e.direction=d;dirs[#dirs+1]={requested=d,actual=e.direction,rotate=e.rotate(),can_place=s.can_place_entity{name=name,position={32.5,20.5},direction=d,force=f}}end;e.direction=0
 local wires={};for id in pairs(e.get_wire_connectors(true)or{})do wires[#wires+1]=id end
 local recipes={};local names={[name]=true};for n,r in pairs(prototypes.recipe)do local match=false;for k in pairs(p.crafting_categories)do if contains(r.categories,k)then match=true end end;if match then recipes[#recipes+1]={name=n,seconds=r.energy,ingredients=r.ingredients,products=r.products,categories=r.categories,enabled=f.recipes[n].enabled,hidden=r.hidden};names[n]=true end end
 table.sort(recipes,function(a,b)return a.name<b.name end);local unlocks={};for n,t in pairs(prototypes.technology)do local relevant={};for _,ef in pairs(t.effects or{})do if ef.type=='unlock-recipe'and names[ef.recipe]then relevant[#relevant+1]=ef.recipe end end;if #relevant>0 then local prerequisites={};for q in pairs(t.prerequisites)do prerequisites[#prerequisites+1]=q end;unlocks[#unlocks+1]={name=n,prerequisites=prerequisites,count=t.research_unit_count,ticks=t.research_unit_energy,ingredients=t.research_unit_ingredients,recipes=relevant}end end
 local fuels={};for n,it in pairs(prototypes.item)do if contains(it.fuel_categories,'chemical')then fuels[#fuels+1]={name=n,joules=it.fuel_value}end end;table.sort(fuels,function(a,b)return a.name<b.name end)
 local item=prototypes.item[name];local r=prototypes.recipe[name];local report={entity={name=name,type=p.type,footprint={p.tile_width,p.tile_height},collision_box=p.collision_box,selection_box=p.selection_box,max_health=p.get_max_health(),max_energy_usage_watts=p.get_max_energy_usage()*60,burner=not not e.burner,burner_effectivity=p.burner_prototype.effectivity,fuel_slots=#e.get_fuel_inventory(),crafting_categories=p.crafting_categories,crafting_speed=e.crafting_speed,module_slots=optional(function()local inv=e.get_module_inventory();return inv and #inv or 0 end),input_slots=#e.get_inventory(defines.inventory.crafter_input),output_slots=#e.get_output_inventory(),fluid_storage_count=e.fluids_count,circuit_connector_ids=wires,circuit_reach=p.get_max_circuit_wire_distance(),surface_conditions=p.surface_conditions},item={name=name,place_result=item.place_result.name,stack_size=item.stack_size,weight=item.weight},building_recipe={enabled=f.recipes[name].enabled,seconds=r.energy,categories=r.categories,ingredients=r.ingredients,products=r.products},compatible_processing_recipes=recipes,chemical_fuels=fuels,unlocks=unlocks,native_directions=dirs,normal_nauvis_placement=dirs[1].can_place,prototype_overrides=false}
 helpers.write_file('smelter-contract/contract.json',helpers.table_to_json(report),false);log('SMELTER_ACTUAL_CONTRACT_CAPTURED')
end)
